CREATE OR REPLACE FUNCTION public.can_read_image(path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND ((split_part(path,'/',1)=auth.uid()::text) OR EXISTS(SELECT 1 FROM public.gym_records r WHERE r.data::text LIKE '%'||path||'%' AND public.gym_access(r.gym_id)) OR EXISTS(SELECT 1 FROM public.client_programs p WHERE p.user_id=auth.uid() AND p.definition::text LIKE '%'||path||'%') OR EXISTS(SELECT 1 FROM public.gym_records r WHERE (r.kind='gym' AND (r.data->>'cover'=path OR r.data->>'logo'=path)) OR (r.kind IN ('workouts','trainers','products') AND r.data::text LIKE '%'||path||'%' AND (EXISTS(SELECT 1 FROM public.client_gym_links l WHERE l.gym_id=r.gym_id AND l.user_id=auth.uid()) OR EXISTS(SELECT 1 FROM public.gym_records m WHERE m.gym_id=r.gym_id AND m.kind='members' AND m.client_id=auth.uid()))))) $$;